css:
@media print {
	@page { size: 58mm auto; margin: 0; }
}

.body_thum {
	font-family: Arial, sans-serif;
	font-size: 12px;
	margin: 0 auto;
	padding: 2mm;
	width: 58mm;
	box-sizing: border-box;
}

.receipt { width: 100%; }

.header { text-align: center; margin-bottom: 4mm; }
.header img.logo { width: 50px; height: auto; margin-bottom: 2mm; }
.header h2 { margin: 0; font-size: 13px; }
.header p { margin: 0; font-size: 10px; }

.details, .items, .totals { margin-bottom: 3mm; }
.details p, .totals p { margin: 0; line-height: 1.4; font-size: 11px; }

.items table { width: 100%; border-collapse: collapse; font-size: 10px; }
.items th, .items td { text-align: left; padding: 1mm 0; }
.items th { border-bottom: 1px solid #000; font-weight: bold; }
.items td { border-bottom: 1px dashed #ccc; }

.totals { text-align: right; }
.totals p { font-size: 11px; font-weight: bold; }

.qr { text-align: center; margin-top: 3mm; }
.qr img { width: 60px; height: 60px; }

@media print {
	.print-heading, .page-head, .navbar, .sidebar-container { display: none !important; }
}
